entries[48265] = { ["name"] = "Unheilige Präsenz", ["text"] = "1 Unheilige RuneSpontanzauber 1 sek. Abklingzeit\nErfüllt den Todesritter mit unheiligem Zorn. Erhöht das Angriffstempo um 15%, das Bewegungstempo um 15% und verringert die globale Abklingzeit aller Fähigkeiten um 0.5 Sek. Es kann jeweils nur eine Präsenz aktiv sein." }
entries[48266] = { ["name"] = "Blutpräsenz", ["text"] = "1 BlutruneSpontanzauber 1 sek. Abklingzeit\nStärkt den Todesritter mit der Präsenz des Blutes, erhöht seinen Schaden um 15% und heilt den Todesritter um 4% des verursachten nicht regelmäßigen Schadens. Es kann jeweils nur eine Präsenz aktiv sein." }
