entries[48998] = { ["name"] = "Gegenangriff", ["text"] = "3% von Grundmana Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nEin Schlag, der aktiv wird, nachdem ein gegnerischer Angriff pariert wurde. Dieser Angriff verursacht (Attack power * 0.2 + 288) Schaden und macht das Ziel 5 sec lang bewegungsunfähig. Auf 'Gegenangriff' kann nicht mit 'Blocken', 'Ausweichen' oder 'Parieren' reagiert werden." }
