entries[49004] = { ["name"] = "Blutgeruch", ["text"] = "Ihr habt eine Chance von 15%, den Effekt 'Blutgeruch' zu erhalten, wenn Ihr direkten Schaden erlitten habt, ausgewichen seid oder pariert habt. Durch diesen Effekt erzeugt Euer nächster Nahkampftreffer 10 Runenmacht.\n(Procchance: 15%)" }
entries[49005] = { ["name"] = "Mal des Blutes", ["text"] = "1 Blutrune 30 Meter Reichweite\nSpontanzauber 3 min Abklingzeit\nBelegt einen Feind mit einem Mal des Blutes. Wenn dieser Feind Schaden verursacht, wird sein Ziel um 4% der eigenen maximalen Gesundheit geheilt. Hält 20 sec lang oder bis zu 20 Treffer lang an." }
