entries[49009] = { ["name"] = "Stich des Flügeldrachen", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerschießt einen Stachel, der das Ziel 30 sec lang einschläfert. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Wenn das Ziel wieder aufwacht, verursacht der Stich im Verlauf von 6 sec insgesamt 2082 Naturschaden. Auf dem Ziel kann gleichzeitig nur ein Biss oder Stich pro Jäger aktiv sein." }
