entries[49020] = { ["name"] = "Auslöschen", ["text"] = "1 Frostrune / 1 Unheilige Rune / -15 Runenmacht Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nEin brutaler, sofortiger Angriff, der 80% Waffenschaden plus 198 verursacht. Für jede Eurer auf das Ziel wirkenden Krankheiten wird der gesamte Schaden um 12.5% erhöht. Die Krankheiten werden durch Anwendung von 'Auslöschen' aufgezehrt." }
