entries[49142] = { ["name"] = "Gefrorene Runenwaffe", ["text"] = "1 Frostrune\nSpontanzauber\nBenötigt Nahkampfwaffe\nErfüllt Eure Runenwaffe mit der Macht des Frosts. Die nächsten 30 Minuten lang haben Eure Nahkampfwaffenschwünge eine Chance, dass Euer Ziel 20 sec lang zusätzlich 2% mehr Schaden durch Frost erleidet. Dieser Effekt ist bis zu 10-mal stapelbar." }
