entries[49172] = { ["name"] = "Wolfsgeist", ["text"] = "Sofort\nDie Lycanthropie verwandelt den Zaubernden nach Ablauf von 5 sec in einen Wolfsgeist. Erhöht den verursachten körperlichen Schaden um 2000, das Angriffstempo um 100% und verhindert, dass der Zaubernde verlangsamt oder aufgehalten werden kann. In dieser Gestalt kann der Zaubernde keine Zauber wirken. Hält 15 sec lang an." }
