entries[49184] = { ["name"] = "Heulende Böe", ["text"] = "1 Frostrune / 1 Unheilige Rune / -15 Runenmacht 20 Meter Reichweite\nSpontanzauber 8 sek. Abklingzeit\nWeht dem Ziel eine eisige Böe entgegen, die allen Gegnern innerhalb von 10 Metern 198 to 214 Frostschaden zufügt." }
