entries[49188] = { ["name"] = "Raureif", ["text"] = "Erhöht die kritische Trefferchance Eurer Fähigkeiten 'Eisige Berührung' und 'Auslöschen' um 5%. Zudem besteht beim Wirken von 'Auslöschen' eine Chance von 5%, dass die Abklingzeit Eurer Fähigkeit 'Heulende Böe' abgeschlossen wird und beim nächsten Wirken von 'Heulende Böe' keine Runen verbraucht werden.\n(Procchance: 5%)" }
entries[49189] = { ["name"] = "Wille der Nekropole", ["text"] = "Sofort\nSchaden, der Eure Gesundheit unter 35% sinken lassen würde, oder den Ihr mit 35% Gesundheit erleidet, wird um 5% verringert." }
