entries[49194] = { ["name"] = "Unheilige Verseuchung", ["text"] = "Opfer Eurer Fähigkeit 'Todesmantel' werden von einer widerwärtigen Wolke unheiliger Insekten umschwärmt, durch die sie im Verlauf von 10 sec 10% des Schadens von 'Todesmantel' erleiden. Zudem wird durch die Insekten verhindert, dass auf das Ziel wirkende Krankheiten gebannt werden können." }
