entries[49200] = { ["name"] = "Akklimatisierung", ["text"] = "Werdet Ihr von einem Zauber getroffen, besteht eine Chance von 10%, dass Euer Widerstand gegen diese Art von Magie 18 Sek. lang erhöht wird. Bis zu 3-mal stapelbar.\n(Procchance: 10%)" }
