entries[49203] = { ["name"] = "Zehrende Kälte", ["text"] = "40 RunenmachtSpontanzauber 1 min Abklingzeit\nEntzieht der Erde unter dem Todesritter jegliche Wärme. Feinde innerhalb von 10 Metern werden in Eis eingeschlossen, das 10 sec lang jegliche ihrer Aktionen verhindert und sie mit Frostfieber ansteckt. Feinde zählen als eingefroren, jeglicher nicht von Krankheiten verursachter Schaden unterbricht den Effekt." }
