entries[49217] = { ["name"] = "Wandernde Seuche", ["text"] = "Wenn von Euch hervorgerufene Krankheiten an einem feindlichen Ziel Schaden verursachen, besteht eine Chance, die Eurer kritischen Nahkampftrefferchance entspricht, dass die Krankheiten am Ziel und allen Feinden im Umkreis von 8 Metern 33% zusätzlichen Schaden verursachen. Dieser Zauber ignoriert Ziele, auf denen Effekte wirken, die durch Schadenseinwirkung unterbrochen werden.\n(500ms Abklingzeit)" }
